/* @lc app=leetcode id=2719 lang=kotlin */ class Solution { fun cnt(s: String, lo: Int, hi: Int): Long = s.fold(Array(2) { LongArray(hi + 1) }.also { it[1][0] = 1 }) { dp, ch -> Array(2) { LongArray(hi + 1) }.also { nd -> (0..1).forEach { t -> (0..hi).forEach { sm -> dp[t][sm].let { v -> if (v != 0L) (0..(if (t == 1) ch - '0' else 9)).forEach { d -> if (sm + d <= hi) (if (t == 1 && d == ch - '0') 1 else 0).let { nt -> nd[nt][sm + d] = (nd[nt][sm + d] + v) % 1_000_000_007 } } } } } } }.let { dp -> (0..1).sumOf { t -> (lo..hi).sumOf { dp[t][it] } } % 1_000_000_007 } fun count(num1: String, num2: String, min_sum: Int, max_sum: Int): Int = ((cnt(num2, min_sum, max_sum) - cnt(num1, min_sum, max_sum) + (if (num1.sumOf { it - '0' } in min_sum..max_sum) 1 else 0) + 1_000_000_007) % 1_000_000_007).toInt() }